import{I as i,o as g,c,j as e,a as r,J as t,w as a,b6 as m,dD as b,dE as p,dF as k,dG as f,dH as S,dI as w,dJ as z,dK as A,dL as v,dM as D,dN as E,nK as I,dO as P,dP as _,nL as B,nM as q,dQ as C,dR as W,dS as x,dT as y,dU as T,nN as M,k as F}from"./chunks/framework.BUXTSoD9.js";import{r as K}from"./chunks/relatedArticles.DIHQAH-1.js";const j={style:{margin:"50px 0"}},L=JSON.parse('{"title":"AI-Programmierwerkzeuge lernen","description":"Lernen Sie den Unterschied zwischen IDE und AI IDE kennen, richten Sie eine lokale Entwicklungsumgebung ein und erstellen Sie mit Trae ein erstes Snake-Spiel. Dieses Kapitel zeigt den kompletten Ablauf von Installation, Projektstart, Ausfuehrung, Fehlerbehebung und Kommunikation mit AI.","frontmatter":{"title":"AI-Programmierwerkzeuge lernen","description":"Lernen Sie den Unterschied zwischen IDE und AI IDE kennen, richten Sie eine lokale Entwicklungsumgebung ein und erstellen Sie mit Trae ein erstes Snake-Spiel. Dieses Kapitel zeigt den kompletten Ablauf von Installation, Projektstart, Ausfuehrung, Fehlerbehebung und Kommunikation mit AI."},"headers":[],"relativePath":"de-de/stage-1/introduction-to-ai-ide/index.md","filePath":"de-de/stage-1/introduction-to-ai-ide/index.md"}'),O={name:"de-de/stage-1/introduction-to-ai-ide/index.md"},U=Object.assign(O,{setup(V){const s="ca. <strong>1 Tag</strong>, in mehreren Sitzungen moeglich",l=K["de-de/stage-1/introduction-to-ai-ide"]??[];return(R,n)=>{const o=i("ChapterIntroduction"),u=i("StepBar"),d=i("ClientOnly"),h=i("RelatedArticles");return g(),c("div",null,[n[1]||(n[1]=e("h1",{id:"anfaenger-ii-ai-programmierwerkzeuge-lernen",tabindex:"-1"},[r("Anfaenger II: AI-Programmierwerkzeuge lernen "),e("a",{class:"header-anchor",href:"#anfaenger-ii-ai-programmierwerkzeuge-lernen","aria-label":"Permalink to “Anfaenger II: AI-Programmierwerkzeuge lernen”"},"​")],-1)),n[2]||(n[2]=e("h2",{id:"kapiteluebersicht",tabindex:"-1"},[r("Kapiteluebersicht "),e("a",{class:"header-anchor",href:"#kapiteluebersicht","aria-label":"Permalink to “Kapiteluebersicht”"},"​")],-1)),t(o,{duration:s,tags:["Lokale Entwicklungsumgebung","IDE und AI IDE","Trae","Agent-Entwicklung"],coreOutput:"1 selbst erstelltes Spiel",expectedOutput:"Ein lokal laufendes Snake-Spiel"},{default:a(()=>[...n[0]||(n[0]=[e("p",null,"Im vorherigen Kapitel haben wir AI-Programmierung im Browser ausprobiert. Eine Web-Plattform ist bequem, aber sie hat Grenzen: Dateien lassen sich schwer langfristig verwalten, lokale Abhaengigkeiten sind eingeschraenkt, und komplexere Projekte werden schnell unuebersichtlich. In diesem Kapitel holen wir die Entwicklungsumgebung auf den eigenen Rechner.",-1),e("p",null,"Sie lernen, was eine IDE ist, wodurch sich eine AI IDE unterscheidet, wie Trae als lokales Werkzeug funktioniert und wie man AI nicht nur zum Chatten, sondern zum Erstellen, Aendern, Ausfuehren und Reparieren von Projekten nutzt. Am Ende haben Sie einen Arbeitsablauf, der dem Alltag echter Entwickler schon deutlich naeher kommt.",-1),e("div",{class:"tip custom-block"},[e("p",{class:"custom-block-title"},"Fortgeschrittenen-Hinweis"),e("p",null,[r("Wenn Sie bereits programmieren koennen und lieber in der Kommandozeile arbeiten, lesen Sie spaeter auch "),e("a",{href:"./../../stage-2/backend/modern-cli/"},"Moderne CLI Coding Werkzeuge"),r(".")])],-1)])]),_:1}),e("div",j,[t(d,null,{default:a(()=>[t(u,{active:0,items:[{title:"Umgebung verstehen",description:"IDE und AI IDE einordnen"},{title:"Lokal ueben",description:"Snake-Spiel mit Trae"},{title:"Werkzeug kennen",description:"IDE-Oberflaeche verstehen"},{title:"Besser fragen",description:"Mit AI klar kommunizieren"}]})]),_:1})]),n[3]||(n[3]=m('<h2 id="_1-welche-umgebung-man-zum-programmieren-braucht" tabindex="-1">1. Welche Umgebung man zum Programmieren braucht <a class="header-anchor" href="#_1-welche-umgebung-man-zum-programmieren-braucht" aria-label="Permalink to “1. Welche Umgebung man zum Programmieren braucht”">​</a></h2><h3 id="_1-1-denkwechsel-bei-problemen-zuerst-ai-fragen" tabindex="-1">1.1 Denkwechsel: Bei Problemen zuerst AI fragen <a class="header-anchor" href="#_1-1-denkwechsel-bei-problemen-zuerst-ai-fragen" aria-label="Permalink to “1.1 Denkwechsel: Bei Problemen zuerst AI fragen”">​</a></h3><p>Beim klassischen Programmierlernen sucht man oft erst im Web: Wie installiere ich Python? Wie konfiguriere ich Conda? Warum haengt <code>npm install</code>? Danach arbeitet man Tutorials Schritt fuer Schritt ab und sucht bei jeder Fehlermeldung erneut.</p><p>Mit einer AI IDE sollten Sie diese Gewohnheit aendern. Wenn Sie nicht wissen, was zu tun ist, fragen Sie zuerst die AI im Seitenpanel. Sie kann Befehle erklaeren, passende Schritte vorschlagen oder sogar direkt fuer Sie ausfuehren.</p><ul><li><strong>Umgebung unklar?</strong> Fragen Sie: &quot;Ich moechte Python schreiben. Bitte pruefe, ob Python installiert ist, und hilf mir bei der Installation, falls es fehlt.&quot;</li><li><strong>Abhaengigkeiten laden nicht?</strong> Schreiben Sie: &quot;Der Download schlaegt fehl. Ist das ein Netzwerkproblem? Bitte hilf mir, eine passende Spiegelquelle zu verwenden.&quot;</li><li><strong>Befehl vergessen?</strong> Fragen Sie: &quot;Bitte erstelle eine neue virtuelle Umgebung mit dem Namen <code>demo</code>.&quot;</li></ul><p>Der wichtige Punkt ist: Sie muessen nicht alle Befehle auswendig kennen. Sie muessen lernen, das Ziel klar zu beschreiben und die AI Schritt fuer Schritt pruefen zu lassen.</p><h3 id="_1-2-warum-werkzeuge-noetig-sind" tabindex="-1">1.2 Warum Werkzeuge noetig sind <a class="header-anchor" href="#_1-2-warum-werkzeuge-noetig-sind" aria-label="Permalink to “1.2 Warum Werkzeuge noetig sind”">​</a></h3><p>Ein paar Codezeilen kann man theoretisch in einem einfachen Texteditor schreiben. Fuer ein wartbares Projekt reicht das aber nicht:</p><ul><li><strong>Ohne Syntaxhervorhebung</strong> sehen Schluesselwoerter, Strings und Kommentare gleich aus.</li><li><strong>Ohne Vervollstaendigung</strong> muss jeder Name exakt selbst getippt werden.</li><li><strong>Ohne Projektansicht</strong> verliert man bei mehreren Dateien schnell den Ueberblick.</li><li><strong>Ohne Debugging</strong> bleibt bei Fehlern oft nur Raten und Log-Ausgabe.</li></ul><p>Eine IDE, also eine integrierte Entwicklungsumgebung, loest diese Probleme. Sie organisiert Dateien, hebt Code farbig hervor, bietet Autovervollstaendigung, startet Programme und hilft beim Debugging.</p><h2 id="_2-was-ist-eine-ide" tabindex="-1">2. Was ist eine IDE? <a class="header-anchor" href="#_2-was-ist-eine-ide" aria-label="Permalink to “2. Was ist eine IDE?”">​</a></h2><div class="info custom-block"><p class="custom-block-title">Vorbereitung</p><p>Wenn Ihnen IDEs noch neu sind, lesen Sie spaeter auch <a href="/easy-vibe-ja-learning-map/zh-cn/appendix/2-development-tools/ide-basics.html">IDE Grundlagen</a>. Dort werden typische Bereiche wie Editor, Terminal, Seitenleiste und Debugger noch einmal in Ruhe erklaert.</p></div><p>Fruehe Entwickler arbeiteten mit einfachen Editoren und Kommandozeilentools. Als Projekte groesser wurden, brauchte man Werkzeuge, die Dateien, Ausfuehrung und Debugging in einer Oberflaeche vereinen. Daraus entstand die IDE.</p><p><img src="'+b+'" alt=""><img src="'+p+'" alt=""></p><p>Bildquelle der Terminal-Oberflaeche: <a href="https://en.wikipedia.org/wiki/File:Emacs-screenshot.png" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/File:Emacs-screenshot.png</a></p><p>Auch heute werden Werkzeuge wie <code>Vim</code> oft auf Servern verwendet.</p><p><img src="'+k+'" alt=""></p><p>Moderne IDEs sind fuer Einsteiger komfortabler. Sie enthalten normalerweise:</p><ul><li><strong>Quellcode-Editor</strong>: Syntaxhervorhebung und Autovervollstaendigung.</li><li><strong>Build- und Startwerkzeuge</strong>: Programme koennen direkt ausgefuehrt werden.</li><li><strong>Debugger</strong>: Breakpoints, Variablenansicht und schrittweises Ausfuehren.</li><li><strong>Projektverwaltung</strong>: Dateien und Ordner bleiben im Zusammenhang sichtbar.</li></ul><p>Die bekannteste leichte IDE ist <strong><a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code</a></strong>. Sie ist erweiterbar und fuer viele Sprachen geeignet.</p><p><img src="'+f+'" alt=""></p><p>VS Code folgt dem Prinzip &quot;Alles ist eine Erweiterung&quot;. Mit Python-Erweiterung wird es zur Python-IDE, mit C++-Erweiterung zur C++-IDE. Ohne Erweiterungen ist es eher ein guter Texteditor.</p><p><img src="'+S+'" alt=""></p><p>Es eignet sich auch sehr gut zum Schreiben von Markdown-Dokumenten.</p><p><img src="'+w+'" alt=""></p><p>Kurz gesagt: Eine IDE ist ein Werkzeugset, das Schreiben, Verwalten, Ausfuehren und Reparieren von Code effizienter macht.</p><h2 id="_3-was-unterscheidet-eine-ai-ide-von-einer-gewoehnlichen-ide" tabindex="-1">3. Was unterscheidet eine AI IDE von einer gewoehnlichen IDE? <a class="header-anchor" href="#_3-was-unterscheidet-eine-ai-ide-von-einer-gewoehnlichen-ide" aria-label="Permalink to “3. Was unterscheidet eine AI IDE von einer gewoehnlichen IDE?”">​</a></h2><p>Eine normale IDE ist ein Werkzeugkasten. Sie koennen Dateien oeffnen, Code schreiben, Programme starten und Erweiterungen installieren. Aber Sie muessen selbst wissen, welche Datei wichtig ist, welcher Befehl ausgefuehrt werden muss und wie eine Fehlermeldung zu lesen ist.</p><p>Eine AI IDE fuegt ein grosses Sprachmodell und haeufig einen Agenten hinzu. Dadurch koennen Sie Aufgaben in natuerlicher Sprache formulieren:</p><ul><li>&quot;Erstelle eine Login-Seite.&quot;</li><li>&quot;Hier ist die Fehlermeldung. Bitte erklaere die Ursache und schlage eine Reparatur vor.&quot;</li><li>&quot;Fasse die Projektstruktur zusammen und erklaere mir, welche Dateien wichtig sind.&quot;</li><li>&quot;Fuege eine Bestenliste zum Spiel hinzu und starte danach die App.&quot;</li></ul><p>Eine gute AI IDE kann Dateien lesen, neue Dateien erzeugen, Code ueber mehrere Dateien hinweg aendern, Befehle im Terminal ausfuehren und nach Ihrer Bestaetigung Tests oder Entwicklungsserver starten.</p><p>VS Code selbst enthaelt inzwischen ebenfalls AI-Funktionen. Trotzdem sind spezialisierte AI IDEs in vielen Aufgaben staerker, weil sie Agentenablaeufe, Kontextverwaltung, Dateiaenderungen und Modellintegration gezielter ausbauen.</p><p><img src="'+z+'" alt=""></p><p>Viele AI IDEs basieren auf VS Code. Wenn Sie die Grundbedienung von VS Code verstehen, koennen Sie deshalb relativ leicht zwischen Trae, Cursor, Kiro, Qoder oder aehnlichen Werkzeugen wechseln.</p><p>Typische AI-IDE-Faehigkeiten sind:</p><ul><li><strong>Codegenerierung und Vervollstaendigung</strong>: Aus wenigen Saetzen oder Pseudocode entsteht lauffaehige Logik.</li><li><strong>Codeverstaendnis und Q&amp;A</strong>: Die IDE beantwortet Fragen zu Dateien, Funktionen und Projektstruktur.</li><li><strong>Refactoring und Optimierung</strong>: Bestehender Code wird nach Ihrer Absicht umgeschrieben.</li><li><strong>Testgenerierung</strong>: Fuer Funktionen und Module koennen Testfaelle erzeugt werden.</li><li><strong>Agentische Ausfuehrung</strong>: Ein Agent kann Dateien erstellen, Abhaengigkeiten installieren, Programme starten und Fehler iterativ reparieren.</li></ul><h3 id="aktuelle-ai-ides-im-ueberblick" tabindex="-1">Aktuelle AI IDEs im Ueberblick <a class="header-anchor" href="#aktuelle-ai-ides-im-ueberblick" aria-label="Permalink to “Aktuelle AI IDEs im Ueberblick”">​</a></h3><details class="details custom-block"><summary>Antigravity</summary><h3 id="antigravity" tabindex="-1"><a href="https://antigravity.google/" target="_blank" rel="noreferrer">Antigravity</a> <a class="header-anchor" href="#antigravity" aria-label="Permalink to “Antigravity”">​</a></h3><p>Antigravity ist eine von Google vorgestellte AI IDE mit Agent-First-Ansatz. Der Agent kann Editor, Terminal und Browser bedienen, Aufgaben planen, Code ausfuehren, Tests starten und Ergebnisse zusammenfassen. Sie eignet sich besonders, wenn man mit Gemini- und anderen modernen Modellen arbeiten moechte.</p></details><details class="details custom-block"><summary>Trae</summary><h3 id="trae" tabindex="-1"><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">Trae</a> <a class="header-anchor" href="#trae" aria-label="Permalink to “Trae”">​</a></h3><p><img src="'+A+'" alt=""></p><p>Trae ist ein AI-Programmierassistent von ByteDance. Es unterstuetzt viele Programmiersprachen, kann Code aus natuerlicher Sprache erzeugen, beim Debugging helfen und Designentwuerfe in React- oder Vue-Komponenten umwandeln. Fuer dieses Kapitel nutzen wir Trae als Beispiel, weil es fuer Einsteiger einen relativ klaren Agentenablauf bietet.</p></details><details class="details custom-block"><summary>Cursor</summary><h3 id="cursor" tabindex="-1"><a href="https://cursor.com/" target="_blank" rel="noreferrer">Cursor</a> <a class="header-anchor" href="#cursor" aria-label="Permalink to “Cursor”">​</a></h3><p>Cursor ist ein AI-Codeeditor auf Basis von VS Code. Er ist besonders stark bei groesseren Codebasen, Multi-File-Aenderungen und Kontextarbeit. Cursor ist sehr beliebt, aber die Pro-Version kostet ungefaehr 20 US-Dollar pro Monat.</p><p><img src="'+v+'" alt=""></p></details><details class="details custom-block"><summary>Qoder</summary><h3 id="qoder" tabindex="-1"><a href="https://qoder.com/" target="_blank" rel="noreferrer">Qoder</a> <a class="header-anchor" href="#qoder" aria-label="Permalink to “Qoder”">​</a></h3><p>Qoder betont transparente Zusammenarbeit und Kontext-Engineering. Es kann Aufgaben in Schritte zerlegen, Ausfuehrung sichtbar machen und eignet sich fuer groessere Projekte, Architekturarbeit und Analyse alter Systeme.</p><p><img src="'+D+'" alt=""></p></details><details class="details custom-block"><summary>CodeBuddy</summary><h3 id="codebuddy" tabindex="-1"><a href="https://copilot.tencent.com/" target="_blank" rel="noreferrer">CodeBuddy</a> <a class="header-anchor" href="#codebuddy" aria-label="Permalink to “CodeBuddy”">​</a></h3><p><img src="'+E+'" alt=""></p><p>CodeBuddy ist ein AI-Programmierwerkzeug von Tencent Cloud. Es unterstuetzt Codevervollstaendigung, Code-Review, mehrere Modelle und Enterprise-Anforderungen wie private Bereitstellung und Compliance.</p></details><details class="details custom-block"><summary>Cline</summary><h3 id="cline" tabindex="-1"><a href="https://cline.bot/" target="_blank" rel="noreferrer">Cline</a> <a class="header-anchor" href="#cline" aria-label="Permalink to “Cline”">​</a></h3><p>Cline ist ein Agent-Plugin fuer VS Code. Es kann ueber verschiedene API-Endpunkte mit unterschiedlichen Modellen arbeiten, unterstuetzt MCP-Werkzeuge und verlangt fuer Aktionen normalerweise eine Nutzerbestaetigung. Es ist gut geeignet, um Ideen schnell in bestehenden VS-Code-Workflows zu testen.</p><p><img src="'+I+'" alt=""></p></details><details class="details custom-block"><summary>Kiro</summary><h3 id="kiro" tabindex="-1"><a href="https://kiro.dev/" target="_blank" rel="noreferrer">Kiro</a> <a class="header-anchor" href="#kiro" aria-label="Permalink to “Kiro”">​</a></h3><p>Kiro ist eine AI-IDE von AWS und integriert sich eng mit Amazon Bedrock sowie AWS-Diensten wie Lambda, S3 oder DynamoDB. Sie eignet sich besonders fuer Cloud-native Entwicklung im AWS-Umfeld.</p></details><div class="tip custom-block"><p class="custom-block-title">Modellhinweis</p><p>Wenn Sie Anthropic-Claude-Modelle stabil nutzen wollen, sind Cursor, Kiro oder Antigravity oft geeignete Optionen, weil sie offizielle oder tiefere Integrationen anbieten.</p></div><h2 id="_4-mit-trae-ein-snake-spiel-lokal-erstellen" tabindex="-1">4. Mit Trae ein Snake-Spiel lokal erstellen <a class="header-anchor" href="#_4-mit-trae-ein-snake-spiel-lokal-erstellen" aria-label="Permalink to “4. Mit Trae ein Snake-Spiel lokal erstellen”">​</a></h2><p>Bis hierhin ging es um Begriffe. Jetzt bringen wir das in die Praxis: Wir erstellen einen leeren Ordner, oeffnen ihn in einer AI IDE, schreiben im Seitenpanel eine klare Aufgabe und lassen Trae ein Snake-Spiel mit React erzeugen.</p><p>Wenn Sie vorher schon auf z.ai oder einer anderen Web-Plattform Code erstellt haben, koennen Sie diesen Code auch herunterladen und lokal in Trae weiterbearbeiten. So bleiben alte Ergebnisse erhalten, und Sie bekommen trotzdem die staerkere lokale Umgebung.</p><h3 id="_4-1-trae-installieren" tabindex="-1">4.1 Trae installieren <a class="header-anchor" href="#_4-1-trae-installieren" aria-label="Permalink to “4.1 Trae installieren”">​</a></h3><p>Trae kann von der offiziellen Website installiert werden. Je nach Region gibt es unterschiedliche Versionen.</p><p><img src="'+P+'" alt=""></p><ul><li><strong>CN-Version</strong>: Fuer Einsteiger in China meist einfacher, oft kostenlos nutzbar und ohne Auslandsnetzwerk bequemer.</li><li><strong>Internationale Version</strong>: Bietet Zugang zu internationalen Modellen, setzt aber passende Netzwerkbedingungen und haeufig ein Abo voraus.</li><li><strong>Drittanbieter-Modelle</strong>: Wenn Sie API-Token fuer Modelle wie DeepSeek, Qwen, Kimi oder andere Anbieter besitzen, koennen Sie diese als Custom Model einbinden.</li></ul><p>Die genaue Version ist weniger wichtig als der Arbeitsablauf: Projektordner oeffnen, Agent starten, Aufgabe klar beschreiben, Ergebnis pruefen.</p><h3 id="_4-2-trae-oberflaeche-verstehen" tabindex="-1">4.2 Trae-Oberflaeche verstehen <a class="header-anchor" href="#_4-2-trae-oberflaeche-verstehen" aria-label="Permalink to “4.2 Trae-Oberflaeche verstehen”">​</a></h3><p>Trae sieht VS Code sehr aehnlich: links Dateibaum, in der Mitte Editor, rechts AI-Panel.</p><p><img src="'+_+'" alt=""></p><p>Das rechte Panel ist das Copilot- oder Agentenfenster. Wenn es nicht sichtbar ist, oeffnen Sie es ueber das Symbol rechts oben.</p><p><img src="'+B+'" alt=""></p><p>Im Seitenpanel finden Sie normalerweise einen <strong>Builder</strong>-Modus. Er funktioniert aehnlich wie ein lokaler z.ai-Agent: Er kann Dateien anlegen, Abhaengigkeiten installieren, Befehle starten und lokale Webseiten oeffnen.</p><p><img src="'+q+'" alt=""></p><p>Es gibt oft mehrere Modi:</p><ul><li><strong>Chat</strong>: Gut fuer Fragen zum aktuellen Projekt oder fuer allgemeine Erklaerungen.</li><li><strong>Builder</strong>: Gut fuer Aufgaben, bei denen Dateien erstellt oder geaendert werden.</li><li><strong>Builder with MCP</strong>: Erweitert den Agenten um zusaetzliche Werkzeuge, etwa externe Dienste oder lokale Integrationen.</li></ul><p>Im Modellmenue koennen Sie das verwendete Modell waehlen. Vermeiden Sie am Anfang nach Moeglichkeit den Auto-Modus, wenn Sie reproduzierbare Ergebnisse wollen. Testen Sie fuer internationale Versionen Modelle wie Gemini oder GPT; fuer chinesische Versionen koennen Kimi, GLM, Qwen oder MiniMax gute Alltagsoptionen sein. Entscheidend ist nicht ein Dogma, sondern ob das Modell Ihre Aufgabe verlaesslich loest.</p><h3 id="_4-3-leeren-projektordner-vorbereiten" tabindex="-1">4.3 Leeren Projektordner vorbereiten <a class="header-anchor" href="#_4-3-leeren-projektordner-vorbereiten" aria-label="Permalink to “4.3 Leeren Projektordner vorbereiten”">​</a></h3><p>Erstellen Sie lokal einen leeren Ordner, zum Beispiel:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>snake-game-react</span></span></code></pre></div><p>Oeffnen Sie diesen Ordner in Trae. Der Dateibaum sollte anfangs leer oder fast leer sein. Damit weiss der Agent klar, dass er ein neues Projekt von Grund auf anlegen soll.</p><details class="details custom-block"><summary>Optional: API oder Coding Plan einbinden</summary><p>Einige Cloud-Anbieter bieten Coding Plans oder Modell-APIs an. Damit kann man Modelle haeufiger oder stabiler nutzen als ueber einzelne Token-Abrechnung.</p><p>Der typische Ablauf:</p><ol><li>Website des Anbieters oeffnen.</li><li>Konto registrieren und anmelden.</li><li>Preis- oder Coding-Plan-Seite finden.</li><li>Passenden Plan kaufen oder eine API aktivieren.</li><li>API Key kopieren.</li><li>In Trae ueber <strong>Add Model</strong> oder <strong>Custom Model</strong> eintragen.</li></ol><p>Fuer erste Uebungen reicht oft ein kostenloses oder sehr guenstiges Modell. Zahlen Sie am Anfang nur kleine Betraege ein, bis Sie wissen, wie lange Ihr Guthaben reicht.</p></details><h3 id="_4-4-snake-spiel-mit-einem-klaren-prompt-erstellen" tabindex="-1">4.4 Snake-Spiel mit einem klaren Prompt erstellen <a class="header-anchor" href="#_4-4-snake-spiel-mit-einem-klaren-prompt-erstellen" aria-label="Permalink to “4.4 Snake-Spiel mit einem klaren Prompt erstellen”">​</a></h3><p>Oeffnen Sie das AI-Seitenpanel, zum Beispiel mit <code>Ctrl+L</code> oder ueber das Chat-Symbol. Geben Sie dann eine konkrete Aufgabe ein:</p><blockquote><p>Bitte implementiere mit React ein Snake-Spiel. Es soll Tastatursteuerung, Essen, Wachstum, Punkteanzeige, Game Over bei Wandkontakt oder Selbstkollision und einen Neustart-Button enthalten. Erstelle das Projekt, installiere fehlende Abhaengigkeiten und starte es lokal. Wenn eine Umgebung fehlt, erklaere zuerst kurz, was installiert werden muss, und hilf mir dann Schritt fuer Schritt.</p></blockquote><p>Der Agent wird normalerweise Dateien anlegen, Abhaengigkeiten installieren und einen Entwicklungsserver starten. Dabei kann er anhalten, wenn er eine Bestaetigung braucht.</p><div class="warning custom-block"><p class="custom-block-title">Wichtiger Hinweis</p><p>Manchmal pausiert ein Agent, weil ein Befehl eine Eingabe erwartet, etwa <code>y</code>, <code>Enter</code>, einen Projektnamen oder eine Auswahl. Wenn Sie unsicher sind, machen Sie einen Screenshot und fragen Sie die AI: &quot;Was soll ich in diesem Schritt tun?&quot;</p></div><p>Typische Situationen:</p><ul><li>Wenn ein Button wie <strong>Run</strong> erscheint, muessen Sie die Ausfuehrung bestaetigen.</li><li>Wenn ein Paketmanager <code>y</code> erwartet, reicht meist die Eingabe <code>y</code>.</li><li>Wenn ein lokaler Entwicklungsserver gestartet wurde, bleibt der Prozess im Terminal aktiv. Das ist normal; oeffnen Sie die angezeigte URL im Browser.</li></ul><p><img src="'+C+'" alt=""></p><p><img src="'+W+'" alt=""></p><p><img src="'+x+'" alt=""></p><p>Wenn das Ergebnis nicht passt, beschreiben Sie das sichtbare Problem:</p><ul><li>&quot;Die Schlange bewegt sich nach Start nicht.&quot;</li><li>&quot;Beim Wandkontakt erscheint kein Game Over.&quot;</li><li>&quot;Der Punktestand wird nicht aktualisiert.&quot;</li><li>&quot;Hier ist die Fehlermeldung. Bitte erklaere und behebe sie.&quot;</li></ul><p>Nach kurzer Zeit sollten Sie ein lauffaehiges Ergebnis sehen.</p><p><img src="'+y+'" alt=""></p><h3 id="_4-5-aenderungen-pruefen-und-zurueckrollen" tabindex="-1">4.5 Aenderungen pruefen und zurueckrollen <a class="header-anchor" href="#_4-5-aenderungen-pruefen-und-zurueckrollen" aria-label="Permalink to “4.5 Aenderungen pruefen und zurueckrollen”">​</a></h3><p>AI IDEs zeigen Aenderungen normalerweise vor oder nach dem Schreiben an. Sie koennen akzeptieren, ablehnen oder einzelne Dateien pruefen.</p><p><img src="'+T+'" alt=""></p><p>Wenn der Agent eine schlechte Aenderung macht, nutzen Sie <strong>Revert</strong> oder die Versionshistorie der IDE. Das ist eine wichtige Gewohnheit: Lassen Sie AI schnell arbeiten, aber behalten Sie Kontrolle ueber die Aenderungen.</p><p><img src="'+M+'" alt=""></p><h2 id="_5-den-generierten-code-verstehen-und-verbessern" tabindex="-1">5. Den generierten Code verstehen und verbessern <a class="header-anchor" href="#_5-den-generierten-code-verstehen-und-verbessern" aria-label="Permalink to “5. Den generierten Code verstehen und verbessern”">​</a></h2><p>Wenn das Spiel laeuft, ist die Arbeit nicht beendet. Jetzt koennen Sie dieselbe AI nutzen, um das Projekt zu verstehen.</p><p>Fragen Sie zum Beispiel:</p><blockquote><p>Bitte erklaere mir von oben nach unten, wie dieses Snake-Spiel funktioniert. Verwende moeglichst wenig Fachwoerter.</p></blockquote><p>Danach koennen Sie gezielt nachhaken:</p><blockquote><p>Wie wird der Koerper der Schlange im Code gespeichert? Kannst du eine Alltagsanalogie verwenden?</p></blockquote><blockquote><p>Wo im Code wird gesteuert, dass sich die Schlange in festen Zeitabstaenden bewegt?</p></blockquote><blockquote><p>Welche Schritte passieren, wenn die Schlange Essen erreicht?</p></blockquote><blockquote><p>Wo werden Wandkollision und Selbstkollision erkannt?</p></blockquote><p>Wenn Sie eine Datei wie <code>SnakeGame.tsx</code> sehen und sie nicht verstehen, fragen Sie:</p><blockquote><p>Bitte teile <code>SnakeGame.tsx</code> in Funktionsbereiche auf und erklaere jeden Bereich in einfachen Worten.</p></blockquote><p>So lernen Sie nicht alle Konzepte auf einmal, sondern erkennen zuerst die Hauptdaten: Schlange, Essen, Punktzahl und Spielzustand. Danach verstehen Sie, wann diese Daten geaendert werden: Bewegung, Essen, Game Over, Neustart.</p><h3 id="_5-1-oberflaeche-gezielt-verbessern" tabindex="-1">5.1 Oberflaeche gezielt verbessern <a class="header-anchor" href="#_5-1-oberflaeche-gezielt-verbessern" aria-label="Permalink to “5.1 Oberflaeche gezielt verbessern”">​</a></h3><p>Sagen Sie nicht nur: &quot;Mach es schoener.&quot; Das ist zu ungenau. Beschreiben Sie konkrete Aenderungen:</p><blockquote><p>Bitte verbessere die Spieloberflaeche:</p><ul><li>Zentriere den Spielbereich.</li><li>Nutze einen hellen Hintergrund.</li><li>Mache Schlange und Essen gut sichtbar.</li><li>Vergroessere die Punktzahl.</li><li>Verwende Blau als Hauptfarbe fuer Buttons.</li></ul></blockquote><p>Fuer Game Over:</p><blockquote><p>Wenn das Spiel vorbei ist, zeige in der Mitte &quot;Game Over&quot; und darunter einen Neustart-Button.</p></blockquote><p>Wenn das Ergebnis noch nicht passt, gehen Sie in kleinen Schritten weiter:</p><blockquote><p>Die Punktzahl soll groesser und auffaelliger sein.</p></blockquote><blockquote><p>Der Spielbereich soll kompakter wirken und mehr Abstand zum Rand haben.</p></blockquote><blockquote><p>Der Neustart-Button soll blau, abgerundet und zentriert sein.</p></blockquote><p>Wenn eine Aenderung Fehler erzeugt, kopieren Sie die Fehlermeldung ins Chatfenster und schreiben Sie: &quot;Dieser Fehler ist nach der Oberflaechenanpassung aufgetreten. Bitte finde die Ursache im aktuellen Projekt und behebe sie.&quot;</p><h3 id="_5-2-gute-referenzen-nutzen" tabindex="-1">5.2 Gute Referenzen nutzen <a class="header-anchor" href="#_5-2-gute-referenzen-nutzen" aria-label="Permalink to “5.2 Gute Referenzen nutzen”">​</a></h3><p>Einsteiger wissen oft noch nicht, was eine gute Architektur oder ein gutes UI ist. Dann hilft es, Referenzen zu verwenden. Wenn Sie auf z.ai bereits ein gutes Ergebnis hatten, kopieren Sie dessen README oder Projektbeschreibung in Trae und bitten Sie:</p><blockquote><p>Bitte vergleiche mein lokales Projekt mit dieser README-Beschreibung und passe Struktur, Funktionen und Oberflaeche so an, dass sie dem beschriebenen Ergebnis naeher kommen.</p></blockquote><p>So erhalten Sie nicht nur &quot;irgendein&quot; Spiel, sondern naehern sich einem konsistenteren Ergebnis.</p><h2 id="_6-ide-oberflaeche-im-detail" tabindex="-1">6. IDE-Oberflaeche im Detail <a class="header-anchor" href="#_6-ide-oberflaeche-im-detail" aria-label="Permalink to “6. IDE-Oberflaeche im Detail”">​</a></h2><p>Nachdem der erste Ablauf funktioniert, lohnt sich ein Blick auf die IDE selbst. Die meisten AI IDEs folgen dem VS-Code-Layout.</p><p>Typische Bereiche:</p><ul><li><strong>Title Bar</strong>: Dateiname, Fenstersteuerung und Hauptmenues.</li><li><strong>Activity Bar</strong>: Wechsel zwischen Dateien, Suche, Git, Erweiterungen und Debugging.</li><li><strong>Side Bar</strong>: Dateibaum oder Suchergebnisse.</li><li><strong>Editor Groups</strong>: Hauptbereich zum Lesen und Schreiben von Code.</li><li><strong>Breadcrumbs</strong>: Pfadnavigation innerhalb der Datei.</li><li><strong>Minimap</strong>: Kleine Codeuebersicht fuer schnelle Orientierung.</li><li><strong>Panel</strong>: Terminal, Ausgabe, Probleme und Debug-Informationen.</li><li><strong>Status Bar</strong>: Umgebung, Branch, Sprache und andere Statusinformationen.</li></ul><p>Wenn Sie diese Bereiche erkennen, koennen Sie AI besser anleiten: &quot;Oeffne die Datei im Editor&quot;, &quot;Starte den Befehl im Terminal&quot;, &quot;Pruefe die Fehlermeldung im Problems-Panel&quot;.</p><h2 id="_7-wie-man-als-einsteiger-besser-mit-ai-spricht" tabindex="-1">7. Wie man als Einsteiger besser mit AI spricht <a class="header-anchor" href="#_7-wie-man-als-einsteiger-besser-mit-ai-spricht" aria-label="Permalink to “7. Wie man als Einsteiger besser mit AI spricht”">​</a></h2><p>AI ist stark, aber sie braucht klare Aufgaben. Der Unterschied zwischen guten und schlechten Ergebnissen liegt oft nicht an der Intelligenz des Modells, sondern daran, wie konkret Sie fragen.</p><h3 id="_7-1-von-vager-idee-zu-konkreter-beschreibung" tabindex="-1">7.1 Von vager Idee zu konkreter Beschreibung <a class="header-anchor" href="#_7-1-von-vager-idee-zu-konkreter-beschreibung" aria-label="Permalink to “7.1 Von vager Idee zu konkreter Beschreibung”">​</a></h3><p>Schlecht:</p><blockquote><p>Hilf mir, eine Website zu bauen.</p></blockquote><p>Besser:</p><blockquote><p>Ich kann noch nicht programmieren. Ich moechte eine einseitige persoenliche Website erstellen, die ich Bewerbern oder Recruitern schicken kann. Die Seite soll oben meinen Namen und einen kurzen Satz haben, in der Mitte drei berufliche Stationen zeigen und unten E-Mail sowie Kontaktmoeglichkeit enthalten. Bitte gib mir eine vollstaendige <code>index.html</code>, die ich direkt im Browser oeffnen kann.</p></blockquote><p>Ergaenzen Sie moeglichst:</p><ol><li>Wofuer das Ergebnis genutzt wird.</li><li>Welche Inhalte enthalten sein muessen.</li><li>Welche Einschraenkungen gelten.</li><li>In welcher Form Sie das Ergebnis brauchen.</li></ol><h3 id="_7-2-erst-lauffaehig-dann-komplex" tabindex="-1">7.2 Erst lauffaehig, dann komplex <a class="header-anchor" href="#_7-2-erst-lauffaehig-dann-komplex" aria-label="Permalink to “7.2 Erst lauffaehig, dann komplex”">​</a></h3><p>Einsteiger wollen oft sofort ein komplettes System: Login, Registrierung, Bestellung, Datenbank, Adminbereich. Das fuehrt schnell zu grossen Codebloecken, die man nicht versteht.</p><p>Besser:</p><ol><li>Erst ein Minimalbeispiel.</li><li>Dann einen Bereich hinzufuegen.</li><li>Danach Oberflaeche verbessern.</li><li>Erst spaeter Datenhaltung, Login oder Deployment.</li></ol><p>Beispiel:</p><blockquote><p>Bitte gib mir zuerst nur ein minimales Beispiel, das im Browser eine Zeile &quot;Das ist meine Startseite&quot; zeigt. Erklaere mir Dateiname, Speichern und Oeffnen Schritt fuer Schritt.</p></blockquote><p>Danach:</p><blockquote><p>Fuege nun einen Bereich &quot;Berufserfahrung&quot; hinzu und sende mir wieder den vollstaendigen Code.</p></blockquote><h3 id="_7-3-screenshots-und-fehlermeldungen-nutzen" tabindex="-1">7.3 Screenshots und Fehlermeldungen nutzen <a class="header-anchor" href="#_7-3-screenshots-und-fehlermeldungen-nutzen" aria-label="Permalink to “7.3 Screenshots und Fehlermeldungen nutzen”">​</a></h3><p>Wenn Sie ein Problem nicht beschreiben koennen, geben Sie AI das, was Sie sehen:</p><ul><li>Kopieren Sie rote Fehlermeldungen.</li><li>Machen Sie Screenshots von falschem Layout.</li><li>Beschreiben Sie knapp, was erwartet war.</li></ul><p>Beispiel:</p><blockquote><p>Hier ist die vollstaendige Fehlermeldung. Ich verstehe das Englisch nicht. Bitte erklaere mir zuerst in einfachen Worten, was ungefaehr passiert ist, und sage mir danach, was ich am einfachsten aendern soll.</p></blockquote><p>Wenn das Modell Bilder unterstuetzt:</p><blockquote><p>Das ist der aktuelle Screenshot und hier ist mein Code. Ich wollte drei Spalten, aber es erscheint nur eine Spalte. Bitte finde die Ursache und gib mir die korrigierte vollstaendige Datei.</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Bildfaehigkeit pruefen</p><p>Nicht jedes Modell kann Screenshots verstehen. Reine LLMs verarbeiten nur Text. Multimodale Modelle koennen Bilder lesen. Wenn Ihr Modell keine Bilder unterstuetzt, kopieren Sie Fehlermeldungen und beschreiben Sie das Layout in Worten.</p></div><h3 id="_7-4-wenn-ai-code-nicht-funktioniert" tabindex="-1">7.4 Wenn AI-Code nicht funktioniert <a class="header-anchor" href="#_7-4-wenn-ai-code-nicht-funktioniert" aria-label="Permalink to “7.4 Wenn AI-Code nicht funktioniert”">​</a></h3><p>Fehler sind normal. Nutzen Sie eine feste Routine:</p><ol><li><strong>Nicht sofort neu anfangen.</strong> Erst Fehlermeldung kopieren.</li><li><strong>Problem isolieren.</strong> Was wurde zuletzt geaendert?</li><li><strong>AI im Projektkontext fragen.</strong> Nicht nur die Fehlermeldung, sondern auch Ziel und letzte Aenderung nennen.</li><li><strong>Kleine Reparatur verlangen.</strong> Keine komplette Neuentwicklung, wenn nur ein Detail kaputt ist.</li><li><strong>Nach jeder Reparatur testen.</strong></li></ol><p>Guter Prompt:</p><blockquote><p>Nach deiner letzten Aenderung startet das Projekt nicht mehr. Hier ist die Fehlermeldung. Bitte erklaere zuerst die Ursache, aendere dann nur die noetigen Stellen und starte danach erneut den Test.</p></blockquote><h3 id="_7-5-ai-nicht-blind-vertrauen" tabindex="-1">7.5 AI nicht blind vertrauen <a class="header-anchor" href="#_7-5-ai-nicht-blind-vertrauen" aria-label="Permalink to “7.5 AI nicht blind vertrauen”">​</a></h3><p>AI kann Dateien aendern, aber Sie bleiben verantwortlich. Gewoehnen Sie sich an drei Kontrollen:</p><ul><li><strong>Diff ansehen</strong>: Welche Dateien wurden geaendert?</li><li><strong>Starten oder testen</strong>: Laeuft das Projekt wirklich?</li><li><strong>Rueckgängig machen koennen</strong>: Wenn etwas schlechter wird, Revert nutzen.</li></ul><p>Das Ziel ist nicht, jeden Code sofort zu verstehen, sondern genug Kontrolle zu behalten, um sinnvoll mit dem Agenten zu arbeiten.</p><h2 id="_8-hauefige-begriffe" tabindex="-1">8. Hauefige Begriffe <a class="header-anchor" href="#_8-hauefige-begriffe" aria-label="Permalink to “8. Hauefige Begriffe”">​</a></h2><table tabindex="0"><thead><tr><th>Begriff</th><th>Bedeutung</th></tr></thead><tbody><tr><td>IDE</td><td>Entwicklungsumgebung zum Schreiben, Starten und Debuggen von Code.</td></tr><tr><td>AI IDE</td><td>IDE mit integriertem Sprachmodell und oft Agentenfaehigkeiten.</td></tr><tr><td>Agent</td><td>AI-System, das mehrschrittige Aufgaben planen und Werkzeuge bedienen kann.</td></tr><tr><td>Terminal</td><td>Befehlsfenster innerhalb oder ausserhalb der IDE.</td></tr><tr><td>Dependency</td><td>Externe Bibliothek, die ein Projekt benoetigt.</td></tr><tr><td>Dev Server</td><td>Lokaler Server, der eine Web-App waehrend der Entwicklung bereitstellt.</td></tr><tr><td>Revert</td><td>Aenderungen auf einen frueheren Zustand zuruecksetzen.</td></tr><tr><td>Prompt</td><td>Die Anweisung, die Sie der AI geben.</td></tr><tr><td>Diff</td><td>Vergleich zwischen altem und neuem Code.</td></tr><tr><td>Build</td><td>Produktions- oder Pruefprozess, der zeigt, ob ein Projekt korrekt gebaut werden kann.</td></tr></tbody></table><h2 id="_9-zusammenfassung" tabindex="-1">9. Zusammenfassung <a class="header-anchor" href="#_9-zusammenfassung" aria-label="Permalink to “9. Zusammenfassung”">​</a></h2><p>In diesem Kapitel haben Sie gelernt:</p><ol><li>Eine IDE ist mehr als ein Texteditor: Sie organisiert, startet und debuggt Projekte.</li><li>Eine AI IDE erweitert die IDE um Sprachmodell, Kontextverstaendnis und Agentenaktionen.</li><li>Trae kann ein lokales Projekt erstellen, Abhaengigkeiten installieren und ein React-Spiel starten.</li><li>AI funktioniert am besten, wenn Sie Ziele, Grenzen und erwartete Ausgabe konkret beschreiben.</li><li>Einsteiger sollten zuerst lauffaehige Minimalversionen erstellen und danach schrittweise verbessern.</li></ol><p>Der naechste sinnvolle Schritt ist, mit einem sehr kleinen eigenen Projekt zu ueben: ein Timer, eine To-do-Liste, ein Mini-Spiel oder eine persoenliche Seite. Wichtig ist nicht, sofort perfekt zu programmieren, sondern den Kreislauf zu beherrschen: beschreiben, erzeugen lassen, ausfuehren, pruefen, nachfragen und verbessern.</p>',158)),t(h,{articles:F(l)},null,8,["articles"])])}}});export{L as __pageData,U as default};
